"""SOURCE-RIGHTS-MATRIX.json v1 (B06-0 R01): rights per provider + product + content type + use.
No term text was opened directly (network policy); every proposed legal status is PENDING_VERIFICATION
(an official-page excerpt was seen) or UNKNOWN (no excerpt). Excerpt readings are recorded separately
and never become a legal status or a B01 grant."""
import json, sys

USES = ["internal_research", "commercial_public_display", "redistribution", "derivation", "automated_access"]
OBS = "2026-10-18"

def src(id, provider, product, version, content_types, third_party, data_url, terms_urls, excerpt, readings,
        conditions, role, notes="", codex_reported=None):
    has_excerpt = excerpt is not None
    uses = {}
    for u in USES:
        r = readings.get(u, "NOT_STATED")
        uses[u] = {"excerpt_reading": r,
                   "proposed_legal_status": "PENDING_VERIFICATION" if has_excerpt and r != "NOT_STATED" else "UNKNOWN"}
    return {
        "id": id, "provider": provider, "product": product, "dataset_version": version,
        "content_types": content_types, "third_party_components": third_party,
        "data_url": data_url,
        "terms": {"urls": terms_urls, "official_text_verified": False, "verified_at": None,
                  "excerpt_observed_at": OBS if has_excerpt else None,
                  "excerpt_channel": "search-index excerpt of the official page (direct fetch blocked)" if has_excerpt else None,
                  "excerpt_summary": excerpt},
        "codex_reported": codex_reported,
        "licence_scope": "this product only; not inherited by or from any other product of the provider",
        "uses": uses, "conditions_seen_in_excerpt": conditions,
        "b01_grant": {"status": "unknown", "uses_granted": [], "rights_reviewer": None,
                      "reason": "no rights_reviewer grant exists; an excerpt is not a grant"},
        "proposed_role": role, "notes": notes,
    }

